(1740018, 236184, 42792, '<td valign="top">Nice idea.  Just a little sober for an anniversary and it''s a bit of a strain to read the words.</td>', 'Nice idea.  Just a little sober for an anniversary and it''s a bit of a strain to read the words.', '2005-09-26 15:34:15.000000', NULL, 1),
