(1740447, 235811, 44776, '<td valign="top">Great expression on the baby.  I''m not sure whether laughter or spitting up is next.  The brightness/contrast is very high.  The teeth kind of disappear in the front and the whole image is quite grainy.</td>', 'Great expression on the baby.  I''m not sure whether laughter or spitting up is next.  The brightness/contrast is very high.  The teeth kind of disappear in the front and the whole image is quite grainy.', '2005-09-26 19:18:11.000000', NULL, 1),
(1740450, 236222, 31831, '<td valign="top">3D effect looks great.</td>', '3D effect looks great.', '2005-09-26 19:19:30.000000', NULL, 1),
(1740452, 236376, 44776, '<td valign="top">I like the light shining through the robe.  If the light coming through the hand were blocked I might like it more.</td>', 'I like the light shining through the robe.  If the light coming through the hand were blocked I might like it more.', '2005-09-26 19:19:41.000000', NULL, 1),
