(1741861, 235027, 5354, '<td valign="top">nice colours, horizon falls off to right, needs foreground interest, boat is confusing the background, image does not use full 640 px - other than that ''nice'' - 6</td>', 'nice colours, horizon falls off to right, needs foreground interest, boat is confusing the background, image does not use full 640 px - other than that ''nice'' - 6', '2005-09-27 08:49:31.000000', NULL, 1),
