(1751546, 236019, 35545, '<td valign="top">Unusual color.  I like it.  A nice change from the others.</td>', 'Unusual color.  I like it.  A nice change from the others.', '2005-10-01 00:31:09.000000', NULL, 1),
(1751549, 236269, 35545, '<td valign="top">I really like the colors and the look on the seal''s face.  I''m not sure that I associate a sleeping seal with a sympathy card, but I didn''t mark you down.  I''d probably put it in a general "blank card" category.</td>', 'I really like the colors and the look on the seal''s face.  I''m not sure that I associate a sleeping seal with a sympathy card, but I didn''t mark you down.  I''d probably put it in a general "blank card" category.', '2005-10-01 00:32:54.000000', NULL, 1),
