(1751595, 236174, 35545, '<td valign="top">I think the pink tone is going a bit too far.  This would have been fine in plain B&amp;W.  Good picture which depicts the thought.</td>', 'I think the pink tone is going a bit too far.  This would have been fine in plain B&W.  Good picture which depicts the thought.', '2005-10-01 00:53:50.000000', NULL, 1),
(1751599, 236331, 35545, '<td valign="top">Pretty colors, but are those marbles or pieces of colored glass?  They don''t look like they''d be good to bite into.</td>', 'Pretty colors, but are those marbles or pieces of colored glass?  They don''t look like they''d be good to bite into.', '2005-10-01 00:55:27.000000', NULL, 1),
(1751739, 235535, 36619, '<td valign="top">if you were going for a vibrant, cheery, cute, adorable, entertaining, pretty, happy, fun shot.... you succeeded. :)</td>', 'if you were going for a vibrant, cheery, cute, adorable, entertaining, pretty, happy, fun shot.... you succeeded. :)', '2005-10-01 03:29:16.000000', NULL, 1),
(1751747, 236163, 36619, '<td valign="top">she just looks busy/preoccupied, not sad about someone being gone. but i guess it could be viewed different ways. it''s cute though, not a bad shot.</td>', 'she just looks busy/preoccupied, not sad about someone being gone. but i guess it could be viewed different ways. it''s cute though, not a bad shot.', '2005-10-01 03:37:00.000000', NULL, 1),
(1751749, 235358, 36619, '<td valign="top">omg! absolutley great!</td>', 'omg! absolutley great!', '2005-10-01 03:40:39.000000', NULL, 1),
(1751751, 234693, 36619, '<td valign="top">i just can''t imagine this as a greeting card, there is no emotion to it.</td>', 'i just can''t imagine this as a greeting card, there is no emotion to it.', '2005-10-01 03:43:44.000000', NULL, 1),
(1751824, 236185, 19831, '<td valign="top">Great detail and clarity. Incredible colors. Beautiful. Smart composition. Very nice.</td>', 'Great detail and clarity. Incredible colors. Beautiful. Smart composition. Very nice.', '2005-10-01 06:09:33.000000', NULL, 1),
(1751825, 236231, 19831, '<td valign="top">Nice idea. Might be a little stronger compositionally if the butterfly were either flipped around or close to the opposite side. Now, with him so close to the left edge and facing out, my eye tends to follow and go out of the image.</td>', 'Nice idea. Might be a little stronger compositionally if the butterfly were either flipped around or close to the opposite side. Now, with him so close to the left edge and facing out, my eye tends to follow and go out of the image.', '2005-10-01 06:12:34.000000', NULL, 1),
(1751828, 234178, 19831, '<td valign="top">Simple, yet elegant. Very smart composition. Lovely photo.</td>', 'Simple, yet elegant. Very smart composition. Lovely photo.', '2005-10-01 06:15:06.000000', NULL, 1),
(1751831, 236254, 19831, '<td valign="top">This is a great photo. Very fitting for the challenge. Great focus, good use of dof. That is the cutest little dog. Although, hehehe, it doesn''t look very happy to be in the mail box. Very clever. Good, strong composition. The image gave me a nice smile. I could definitely see this as a card. One of my favorites of the challenge. Very well done.</td>', 'This is a great photo. Very fitting for the challenge. Great focus, good use of dof. That is the cutest little dog. Although, hehehe, it doesn''t look very happy to be in the mail box. Very clever. Good, strong composition. The image gave me a nice smile. I could definitely see this as a card. One of my favorites of the challenge. Very well done.', '2005-10-01 06:19:35.000000', NULL, 1),
(1751919, 235529, 43191, '<td valign="top">This is too cute!</td>', 'This is too cute!', '2005-10-01 09:19:32.000000', NULL, 1),
(1752139, 236273, 36616, '<td valign="top">Perfect expression and interpretation</td>', 'Perfect expression and interpretation', '2005-10-01 12:24:17.000000', NULL, 1),
(1752141, 235743, 36616, '<td valign="top">Sharp pic but may have had more impact in colour - too dark overall for my taste</td>', 'Sharp pic but may have had more impact in colour - too dark overall for my taste', '2005-10-01 12:25:07.000000', NULL, 1),
(1752152, 236349, 36616, '<td valign="top">Great clarity, focus etc.<br/>I''ll have to come to S. Africa one day and perhaps get one of those lenses! I''m jealous</td>', 'Great clarity, focus etc.I''ll have to come to S. Africa one day and perhaps get one of those lenses! I''m jealous', '2005-10-01 12:27:59.000000', NULL, 1),
