(1752362, 236115, 15002, '<td valign="top">Composition is good, meets the challenge well, expression on the duck is great.  DOF could be a bit deeper front and back.</td>', 'Composition is good, meets the challenge well, expression on the duck is great.  DOF could be a bit deeper front and back.', '2005-10-01 13:54:58.000000', NULL, 1),
