(1753954, 236198, 37961, '<td valign="top">I love how the light is focused on the two men, leaving a dark void around and above them. Great Editing.</td>', 'I love how the light is focused on the two men, leaving a dark void around and above them. Great Editing.', '2005-10-02 16:03:22.000000', NULL, 1),
(1753957, 236160, 37961, '<td valign="top">Excellent. everything is perfect about this.</td>', 'Excellent. everything is perfect about this.', '2005-10-02 16:05:11.000000', NULL, 1),
(1753970, 236231, 39349, '<td valign="top">I really like this photo but the only problem I have with it......well it''s not really a problem just a setup issue really, would be to change the main subject to the right side of the frame. In other words, line the subject up in the right hand side third of the shot. This would allow for the shadow to continue through the left hand side of the image producing a more dramatic effect. IMHO. Still, I give you a 7 for a good shot with killer contrast and good dof.</td>', 'I really like this photo but the only problem I have with it......well it''s not really a problem just a setup issue really, would be to change the main subject to the right side of the frame. In other words, line the subject up in the right hand side third of the shot. This would allow for the shadow to continue through the left hand side of the image producing a more dramatic effect. IMHO. Still, I give you a 7 for a good shot with killer contrast and good dof.', '2005-10-02 16:24:49.000000', NULL, 1),
(1753973, 235678, 39349, '<td valign="top">Slight tilt to the left...otherwise nice shot.</td>', 'Slight tilt to the left...otherwise nice shot.', '2005-10-02 16:28:19.000000', NULL, 1),
